\caption{Analysis overview. We identify three effectiveness conditions for detect-and-reweight, from which an adaptive $\bstar$ follows as corollary (\S\ref{sec:method}).}
\label{fig:overview}
\end{figure}

Let $\mathcal{D} = \mathcal{D}_{\mathrm{real}} \cup \mathcal{D}_{\mathrm{synth}}$ denote a pretraining corpus with token-level contamination ratio $\rho = |\mathcal{D}_{\mathrm{synth}}| / |\mathcal{D}|$, assumed unknown~\citep{cheng2025contamination}.
A detector assigns each sample $x$ a synthetic probability $q(x) \in [0,1]$; following \citet{drayson2025detection}, we weight each sample as $w(x) = (1 - q(x))^{b}$, where $b \geq 0$ is a sharpening exponent ($b{=}0$ recovers uniform training).
Rather than selecting $b$ via grid search~\citep{drayson2025detection}, we derive $b$ per-batch from the batch's $q$-score distribution using two opposing constraints.

Given a batch $\mathcal{B} = \{x_1, \ldots, x_B\}$ with scores $q_i = q(x_i)$ and weights $w_i(b) = (1 - q_i)^{b}$:

\paragraph{Quality floor.}
Let $r_i = \mathbf{1}[q_i \leq 0.5]$ indicate likely-real samples. The \emph{effective real proportion} $\aeff(b) = \sum_i w_i(b) r_i / \sum_i w_i(b)$ measures weight allocated to real samples.
We require $\aeff(b) \geq \tau$, yielding a lower bound $b_\tau$ on the exponent, motivated by convergence theory under contamination~\citep{wang2026survive}.
$\aeff$ correlates with the true batch-level real fraction at Pearson $r \approx 0.70$ (Appendix~\ref{app:alpha_validation}); limitations are discussed in \S\ref{sec:discussion}.

\paragraph{Stability ceiling.}
Kish's effective sample size $\mathrm{ESS}(b) = (\sum_i w_i)^2 / \sum_i w_i^2$~\citep{kish1965survey} decreases monotonically in $b$ (Appendix~\ref{app:proofs}).
We require $\mathrm{ESS}(b) \geq \nmin$, yielding an upper bound $\bess$.

\paragraph{Adaptive $\bstar$.}
Since $\aeff$ is non-decreasing and ESS is decreasing in $b$, the two constraints define an interval $[b_\tau, \bess]$.
The optimal exponent implements \emph{minimum intervention}:
\begin{equation}
  b^{*} = \begin{cases}
    0        & \text{if } \aeff(0) \geq \tau, \\
    b_\tau   & \text{if } b_\tau \leq \bess, \\
    \bess & \text{otherwise (stability precedence)},
  \end{cases}
  \label{eq:bstar}
\end{equation}
applying the smallest $b$ that achieves the quality floor.
Each batch falls into one of three regimes---clean, $\aeff$-binding, or ESS-binding---whose frequencies we analyze in \S\ref{sec:regime}.
Given $\bstar$, normalized weights $\pi_i = w_i(\bstar) / \sum_j w_j(\bstar)$ define the weighted loss $\mathcal{L} = \sum_i \pi_i \ell_i$; $\bstar$ is found via bisection (Algorithm~\ref{alg:bstar}, Appendix~\ref{app:algorithm}).
Defaults: $\tau{=}0.7$, $\nmin{=}\lfloor B/2 \rfloor$; sensitivity in \S\ref{sec:sensitivity}.
